/**
 * @file ndviLayer.js
 * @description Manages rendering and opacity of dynamic XYZ raster tile overlays
 * generated by Google Earth Engine for Sentinel-2 NDVI visualization.
 */

/* global L */

export class NdviLayerManager {
  /**
   * @param {L.Map} map - Active Leaflet map instance
   */
  constructor(map) {
    this.map = map;
    this.currentTileLayer = null;
    this.defaultOpacity = 0.75;
  }

  /**
   * Mounts a new dynamic XYZ raster tile layer onto the map.
   * @param {string} tileUrlTemplate - Dynamic XYZ URL template (e.g. from Earth Engine)
   * @param {number} [opacity=0.75] - Layer opacity between 0.0 and 1.0
   * @returns {L.TileLayer}
   */
  setNdviLayer(tileUrlTemplate, opacity = this.defaultOpacity) {
    this.removeCurrentLayer();

    if (!tileUrlTemplate) return null;

    this.currentTileLayer = L.tileLayer(tileUrlTemplate, {
      opacity: opacity,
      maxZoom: 20,
      attribution: "Sentinel-2 &copy; ESA / Google Earth Engine"
    });

    this.currentTileLayer.addTo(this.map);
    return this.currentTileLayer;
  }

  /**
   * Updates opacity of the currently mounted raster layer.
   * @param {number} opacity - Opacity value between 0.0 and 1.0
   */
  setOpacity(opacity) {
    if (this.currentTileLayer) {
      this.currentTileLayer.setOpacity(opacity);
    }
  }

  /**
   * Removes active NDVI tile layer from map.
   */
  removeCurrentLayer() {
    if (this.currentTileLayer && this.map.hasLayer(this.currentTileLayer)) {
      this.map.removeLayer(this.currentTileLayer);
      this.currentTileLayer = null;
    }
  }
}

